import{_ as o,o as t,c as n,a2 as r}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Core Features & Tools","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md"}'),s={name:"guide/features.md"};function a(i,e,l,c,d,g){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="core-features-tools" tabindex="-1">Core Features &amp; Tools <a class="header-anchor" href="#core-features-tools" aria-label="Permalink to &quot;Core Features &amp; Tools&quot;">​</a></h1><hr><h2 id="screenshot-studio" tabindex="-1">📸 Terminal Screenshot Studio <a class="header-anchor" href="#screenshot-studio" aria-label="Permalink to &quot;📸 Terminal Screenshot Studio {#screenshot-studio}&quot;">​</a></h2><p>Capture Carbon.sh-style aesthetic terminal snapshots with custom backgrounds, shadows, and branding:</p><ul><li><strong>Quick Dropdown</strong>: Click <strong>Screenshot</strong> in the top tab bar to instantly <strong>Copy to Clipboard</strong> or <strong>Save to Computer</strong>.</li><li><strong>Screenshot Studio Modal</strong>: Open the full studio to customize: <ul><li><strong>Background Gradient</strong>: Toggle on/off or choose between <em>Indigo</em>, <em>Slate</em>, <em>Cyber</em>, <em>Sunset</em>, <em>Emerald</em>, <em>Rose</em>, <em>Obsidian</em>, and <em>Transparent</em>.</li><li><strong>Canvas Padding</strong>: Adjust padding dynamically (<code>0px</code> tight crop, <code>16px</code>, <code>36px</code>, <code>56px</code>).</li><li><strong>Window Controls</strong>: Toggle macOS traffic light buttons (Red, Yellow, Green).</li><li><strong>Native Save Dialog</strong>: Interactively browse and choose your target folder on your computer.</li></ul></li></ul><hr><h2 id="system-fonts" tabindex="-1">🔤 Dynamic System Font Management <a class="header-anchor" href="#system-fonts" aria-label="Permalink to &quot;🔤 Dynamic System Font Management {#system-fonts}&quot;">​</a></h2><p>TermBolt avoids hardcoded font lists and queries all fonts installed on your computer dynamically via the <strong>System Font Repository Pattern</strong>:</p><ul><li><strong>Windows</strong>: Queries the Windows Registry (<code>HKLM</code> &amp; <code>HKCU</code> Fonts) and <code>%WINDIR%\\Fonts</code>.</li><li><strong>macOS</strong>: Reads <code>/System/Library/Fonts</code>, <code>/Library/Fonts</code>, and <code>~/Library/Fonts</code>.</li><li><strong>Linux</strong>: Scans via <code>fontconfig</code> (<code>fc-list</code>) and <code>/usr/share/fonts</code>.</li><li><strong>Smart Grouping</strong>: Automatically categorizes fonts into <strong>Monospace Fonts</strong> (e.g. <code>Cascadia Code</code>, <code>Fira Code</code>, <code>JetBrains Mono</code>, <code>Consolas</code>, Nerd Fonts) and <strong>All Installed System Fonts</strong>.</li><li><strong>Custom Font Mode</strong>: Easily toggle to manual text entry to specify any bespoke font name.</li></ul><hr><h2 id="master-vault" tabindex="-1">🔒 Encrypted Master Vault <a class="header-anchor" href="#master-vault" aria-label="Permalink to &quot;🔒 Encrypted Master Vault {#master-vault}&quot;">​</a></h2><ul><li><strong>Zero-Knowledge Encryption</strong>: Your server passwords and SSH private keys are never stored in plaintext. They are protected using <strong>PBKDF2 SHA-256 (100,000 iterations)</strong> and authenticated <strong>AES-256-GCM</strong> encryption.</li><li><strong>Auto-Lock Security</strong>: Automatically locks credential access after inactivity.</li></ul><hr><h2 id="cloud-sync" tabindex="-1">☁️ End-to-End Encrypted Cloud Sync <a class="header-anchor" href="#cloud-sync" aria-label="Permalink to &quot;☁️ End-to-End Encrypted Cloud Sync {#cloud-sync}&quot;">​</a></h2><ul><li><strong>Cryptographic Binary Snapshots</strong>: Export your entire server fleet, folders, snippets, and button bars into a <code>.termbolt</code> binary snapshot encrypted with AES-256-GCM.</li><li><strong>Google Drive Integration</strong>: Connect your Google account with OAuth 2.0 PKCE loopback authentication.</li><li><strong>Interactive Conflict Resolver</strong>: Compare local vs remote versions and resolve conflicts per item during snapshot restoration.</li></ul><hr><h2 id="sftp-manager" tabindex="-1">📂 Server-to-Server SFTP File &amp; Directory Copying <a class="header-anchor" href="#sftp-manager" aria-label="Permalink to &quot;📂 Server-to-Server SFTP File &amp; Directory Copying {#sftp-manager}&quot;">​</a></h2><p>TermBolt includes a comprehensive, cross-platform file management and server-to-server copying suite:</p><ul><li><strong>Zero Local Disk Buffering</strong>: Direct streaming between remote SSH/SFTP servers in memory chunks without downloading files to your local hard drive.</li><li><strong>Dual Host Selectors</strong>: Both Left and Right panes feature a dropdown to choose <strong>any host</strong> (Local Machine or any configured remote SSH server).</li><li><strong>Recursive Directory Transfers</strong>: Seamlessly copy entire directory trees with all subfolders and files.</li><li><strong>One-Click Pane Swap ($\\rightleftarrows$)</strong>: Instantly swap Left and Right host panes and paths.</li><li><strong>Directory Operations</strong>: Create new directories on remote or local filesystems, perform bulk deletions with confirmation dialogs, and filter files instantly.</li><li><strong>Live Transfer Progress</strong>: Real-time progress bar and status notifications tracking transferred items and completion.</li><li><strong>100% Cross-Platform</strong>: Fully compatible across Windows, macOS, and Linux.</li></ul><hr><h2 id="terminal-engine" tabindex="-1">⚡ Synchronized Terminal Engine &amp; Persistent Tab Lifecycle <a class="header-anchor" href="#terminal-engine" aria-label="Permalink to &quot;⚡ Synchronized Terminal Engine &amp; Persistent Tab Lifecycle {#terminal-engine}&quot;">​</a></h2><ul><li><strong>Persistent Multi-Tab Sessions</strong>: Terminal processes and buffers remain continuously mounted in memory across tab switches with zero session interruptions or unexpected disconnects.</li><li><strong>Configurable Idle Keep-Alive</strong>: Choose how long idle terminal sessions remain open (from 5 minutes, 15 minutes, 1 hour, up to Indefinite / Always Keep Alive).</li><li><strong>SSH Keep-Alive Heartbeat</strong>: Periodic keepalive ping packets prevent router and firewall disconnections during idle periods.</li><li><strong>Native ResizeObserver</strong>: Continuous synchronization between container viewport and the backend PTY/SSH shell prevents bottom clipping and cursor overdrawing.</li><li><strong>10,000-Line Scrollback</strong>: High-capacity buffer with instantaneous scrolling on keyboard activity.</li><li><strong>In-Terminal Find (<code>Ctrl+F</code>)</strong>: Floating search widget with case-matching and quick navigation.</li></ul>',22)])])}const p=o(s,[["render",a]]);export{m as __pageData,p as default};
